// Writes the compiled ABI + bytecode into @quvr/services as a typed TS module: the server deploys
// and publishes with it, so the publisher key never leaves the server. Run: npm run export
const fs = require("fs");
const path = require("path");
const src = path.join(__dirname, "../artifacts/contracts/QuvrRiskOracle.sol/QuvrRiskOracle.json");
const a = JSON.parse(fs.readFileSync(src, "utf8"));
const out = path.join(__dirname, "../../packages/services/src/oracle/artifact.ts");
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(
  out,
  "// Generated by contracts/scripts/export-artifact.cjs from QuvrRiskOracle.sol. Do not edit.\n" +
    `export const ORACLE_ABI = ${JSON.stringify(a.abi, null, 2)} as const;\n\n` +
    `export const ORACLE_BYTECODE = "${a.bytecode}" as const;\n`,
);
console.log("exported", out, `(${(a.deployedBytecode.length - 2) / 2} bytes deployed)`);

// Uniswap v4 hook + CREATE2 factory (deployed from the server with a mined salt).
const hook = JSON.parse(fs.readFileSync(path.join(__dirname, "../artifacts/contracts/QuvrRiskHook.sol/QuvrRiskHook.json"), "utf8"));
const fac = JSON.parse(fs.readFileSync(path.join(__dirname, "../artifacts/contracts/Create2Deployer.sol/Create2Deployer.json"), "utf8"));
const hookOut = path.join(__dirname, "../../packages/services/src/oracle/hook-artifact.ts");
fs.writeFileSync(
  hookOut,
  "// Generated by contracts/scripts/export-artifact.cjs. Do not edit.\n" +
    `export const HOOK_ABI = ${JSON.stringify(hook.abi, null, 2)} as const;\n\n` +
    `export const HOOK_BYTECODE = "${hook.bytecode}" as const;\n\n` +
    `export const CREATE2_ABI = ${JSON.stringify(fac.abi, null, 2)} as const;\n\n` +
    `export const CREATE2_BYTECODE = "${fac.bytecode}" as const;\n`,
);
console.log("exported", hookOut);
